import {defaults,fields,types,topologies,topologyOf,validateState,bleedSummary} from './circuits.mjs';
import {audioTaper,frequencyResponse,responseAt,magnitudeDB} from './engine.mjs';
import {renderGraph,graphLimits} from './graph.mjs';
const $=s=>document.querySelector(s),form=$('#designer-inputs'),field=k=>form.elements.namedItem(k),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
let state={...defaults},points=[];
function fill(){for(const [key,value] of Object.entries(defaults)){const shown=key==='toneCap'?value/1000:value;field(key).value=shown;field(key).defaultValue=shown;}}
function visibility(){const topology=topologyOf({type:field('type').value,topology:field('topology').value});$('#custom-topology').hidden=field('type').value!=='custom';field('topology').disabled=field('type').value!=='custom';for(const key of ['bleedC','bleedR']){const visible=topology!=='none'&&(key==='bleedC'||topology!=='capacitor');field(key).closest('label').hidden=!visible;field(key).disabled=!visible;}$('#network-info').textContent=topology==='none'?'No bypass network across the volume control.':topology==='capacitor'?'A capacitor connects volume input to the wiper/output.':topology==='parallel'?'The capacitor and resistor each connect across volume input and output, in parallel.':'The capacitor and resistor form one series branch between volume input and output.';}
function update(){
 visibility();const next={...state,type:field('type').value,topology:field('topology').value};for(const key of Object.keys(fields)){const input=field(key);if(!input.disabled)next[key]=input.value.trim()===''?NaN:Number(input.value)*(key==='toneCap'?1000:1);input.removeAttribute('aria-invalid');}
 try{validateState(next);state=next;points=frequencyResponse(state);$('#designer-error').textContent='';$('#response-content').hidden=false;$('#circuit-summary').hidden=false;renderGraph($('#response-graph'),points,state.volume);$('#volume-value').textContent=state.volume.toFixed(1)+' / 10';$('#wiper-position').textContent=(audioTaper(state.volume)*100).toFixed(2)+'% of the pot resistance from ground to wiper';$('#graph-note').textContent=state.volume===0?'Volume 0: output is muted. Zero output is drawn at the −100 dB display floor.':points.some(p=>p.current<=graphLimits.min||p.reference<=graphLimits.min||p.current>=graphLimits.max||p.reference>=graphLimits.max)?'Some response lies outside the −100 to +40 dB display range. See numeric samples below.':'Both curves use the same source-voltage reference. They are not independently normalised.';
 const summary=[['Pickup',`${state.pickupR}kΩ / ${state.pickupL}H / ${state.pickupC}pF`],['Volume potentiometer',`${state.volumePot}kΩ · audio taper`],['Tone potentiometer',`${state.tonePot}kΩ · held at 10`],['Tone control capacitor',`${state.toneCap/1000}µF`],['Treble bleed network',bleedSummary(state)],['Volume position',`${state.volume.toFixed(1)} / 10`],['Load',`${state.loadR}MΩ / ${state.cableC}pF`]];$('#summary-values').replaceChildren(...summary.map(([title,value])=>{const row=el('div');row.append(el('dt',title),el('dd',value));return row;}));
 $('#response-samples').replaceChildren(...[20,100,1000,5000,10000,20000].map(f=>{const row=el('tr');row.append(el('th',f.toLocaleString('en-GB')+' Hz'),el('td',state.volume===0?'Muted':magnitudeDB(responseAt(state,f)).toFixed(2)+' dB'),el('td',magnitudeDB(responseAt({...state,volume:10},f)).toFixed(2)+' dB'));return row;}));
 }catch(error){points=[];$('#designer-error').textContent=error.message;$('#response-content').hidden=true;$('#circuit-summary').hidden=true;for(const [key,meta] of Object.entries(fields)){const input=field(key);if(!input.disabled&&(!Number.isFinite(next[key])||next[key]<meta.min||next[key]>meta.max))input.setAttribute('aria-invalid','true');}}
}
field('volume').addEventListener('input',update);field('volume').addEventListener('change',update);
form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('input',update);form.addEventListener('change',update);form.addEventListener('reset',()=>{state={...defaults};fill();update();});
fill();update();
if(typeof ResizeObserver!=='undefined')new ResizeObserver(()=>{if(points.length)renderGraph($('#response-graph'),points,state.volume);}).observe($('#response-graph'));
